def countIncreasingQuadruplets(nums):
    n = len(nums)
    total = 0
    for j in range(1, n - 2):
        for k in range(j + 1, n - 1):
            if nums[j] > nums[k]:
                left = sum(1 for i in range(j) if nums[i] < nums[k])
                right = sum(1 for l in range(k + 1, n) if nums[l] > nums[j])
                total += left * right
    return total

Problem2617.python:
def minVisitedCells(grid):
    m, n = len(grid), len(grid[0])
    INF = float("inf")
    dist = [[INF] * n for _ in range(m)]
    dist[0][0] = 1
    for r in range(m):
        for c in range(n):
            if r == 0 and c == 0:
                continue
            for p in range(c):
                if p + grid[r][p] >= c:
                    dist[r][c] = min(dist[r][c], dist[r][p] + 1)
            for q in range(r):
                if q + grid[q][c] >= r:
                    dist[r][c] = min(dist[r][c], dist[q][c] + 1)
    return dist[m - 1][n - 1] if dist[m - 1][n - 1] != INF else -1

Problem2745.python:
def longestNewString(x, y, z):
    START, AB, BB, AA = 0, 1, 2, 3
    best = [[[-1] * 4 for _ in range(y + 1)] for _ in range(x + 1)]
    best[0][0][START] = 0
    answer = 0
    for i in range(x + 1):
        for j in range(y + 1):
            if i > 0:
                for st in (START, AB, BB):
                    if best[i - 1][j][st] >= 0:
                        best[i][j][AA] = max(best[i][j][AA], best[i - 1][j][st])
            if j > 0:
                for st in (START, AA):
                    if best[i][j - 1][st] >= 0:
                        best[i][j][BB] = max(best[i][j][BB], best[i][j - 1][st])
            if best[i][j][START] >= 0 or best[i][j][BB] >= 0:
                best[i][j][AB] = z
            answer = max([answer] + [2 * (i + j + k) for k in best[i][j] if k >= 0])
    return answer

Problem2750.python:
def goodSplits(nums):
    MOD = 10**9 + 7
    ways = [0] * (len(nums) + 1)
    ways[0] = 1
    for i in range(1, len(nums) + 1):
        for j in range(i):
            if sum(nums[j:i]) == 1:
                ways[i] += ways[j]
    return ways[len(nums)] % MOD

Problem2963.python:
def countGoodPartitions(nums):
    MOD = 10**9 + 7
    first, last = {}, {}
    for idx, v in enumerate(nums):
        first.setdefault(v, idx)
        last[v] = idx
    ways = [0] * (len(nums) + 1)
    ways[0] = 1
    for i in range(1, len(nums) + 1):
        for j in range(i):
            if all(first[v] >= j and last[v] < i for v in nums[j:i]):
                ways[i] += ways[j]
    return ways[len(nums)] % MOD

Problem3101.python:
def countAlternatingSubarrays(nums):
    total = 0
    streak = 0
    for i in range(len(nums)):
        if i > 0 and nums[i] != nums[i - 1]:
            streak += 1
        else:
            streak = 1
        total += streak
    return total

Problem3287.python:
def maxSequenceValue(nums, k):
    n = len(nums)
    pre = [[set() for _ in range(k + 1)] for _ in range(n + 1)]
    for i in range(n + 1):
        pre[i][0] = {0}
    for i in range(1, n + 1):
        for c in range(1, k + 1):
            pre[i][c] = pre[i - 1][c] | {a | nums[i - 1] for a in pre[i - 1][c - 1]}
    suf = [[set() for _ in range(k + 1)] for _ in range(n + 1)]
    suf[n][0] = {0}
    for i in range(n - 1, -1, -1):
        suf[i][0] = {0}
        for c in range(1, k + 1):
            suf[i][c] = suf[i + 1][c] | {b | nums[i] for b in suf[i + 1][c - 1]}
    best = 0
    for split in range(k, n - k + 1):
        for a in pre[split][k]:
            for b in suf[split][k]:
                best = max(best, a ^ b)
    return best

Problem3290.python:
def maxMultiplicationScore(a, b):
    m, n = len(a), len(b)
    NEG = float("-inf")
    dp = [[NEG] * (n + 1) for _ in range(m + 1)]
    for j in range(n + 1):
        dp[0][j] = 0
    for t in range(1, m + 1):
        for j in range(1, n + 1):
            dp[t][j] = dp[t][j - 1]
            if dp[t - 1][j - 1] != NEG:
                dp[t][j] = max(dp[t][j], dp[t - 1][j - 1] + a[t - 1] * b[j - 1])
    return dp[m][n]
